import{_ as t,o as a,c as s,an as n}from"./chunks/framework.CYOK54rb.js";const g=JSON.parse('{"title":"Embedding in all kinds of formats","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/embedding.md","filePath":"concepts/embedding.md"}'),o={name:"concepts/embedding.md"};function i(d,e,l,m,r,c){return a(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="Embedding-in-all-kinds-of-formats" tabindex="-1">Embedding in all kinds of formats <a class="header-anchor" href="#Embedding-in-all-kinds-of-formats" aria-label="Permalink to &quot;Embedding in all kinds of formats {#Embedding-in-all-kinds-of-formats}&quot;">​</a></h1><p>This page explains where <span class="gm-name">GoMeta</span>&#39;s metadata can be embedded — in the comments of all kinds of codes and formats, the reach <span class="gm-name">GoMeta</span> is meant for — and how: the form it takes in the formats this release reads.</p><p><span class="gm-name">GoMeta</span>&#39;s metadata lives in comments, so the file stays an ordinary file of its format and the host language never sees the metadata. Every format has its <a href="/reference/syntax-and-semantics#comment-marker">comment marker</a> — <code>#</code> in Julia, <code><span class="gm-nb">//</span></code> in the C family (e.g. C, Rust, etc.), <code>%</code> in LaTeX — and the <a href="/reference/syntax-and-semantics#GoMeta-marker"><span class="gm-name">GoMeta</span> marker</a> is that marker followed by the tilde: <code class="gm-ml"><span class="gm-nb"><span class="gm-sg">#~</span></span></code>, <code class="gm-ml"><span class="gm-nb"><span class="gm-sg">//~</span></span></code>, <code class="gm-ml"><span class="gm-nb"><span class="gm-sg">%~</span></span></code>. <span class="gm-name">GoMeta</span>&#39;s comment and its close are built the same way, so a file in any of these formats carries the same structure line for line:</p><table tabindex="0"><thead><tr><th style="text-align:right;"></th><th style="text-align:right;">Julia</th><th style="text-align:right;">the C family</th><th style="text-align:right;">LaTeX</th></tr></thead><tbody><tr><td style="text-align:right;">the comment marker</td><td style="text-align:right;"><code>#</code></td><td style="text-align:right;"><code>//</code></td><td style="text-align:right;"><code>%</code></td></tr><tr><td style="text-align:right;">the <span class="gm-name">GoMeta</span> marker — a <a href="/reference/syntax-and-semantics#metaLine">metaLine</a></td><td style="text-align:right;"><code class="gm-ml"><span class="gm-sg">#~</span></code></td><td style="text-align:right;"><code class="gm-ml"><span class="gm-sg">//~</span></code></td><td style="text-align:right;"><code class="gm-ml"><span class="gm-sg">%~</span></code></td></tr><tr><td style="text-align:right;"><span class="gm-name">GoMeta</span>&#39;s comment</td><td style="text-align:right;"><code>##</code></td><td style="text-align:right;"><code>//#</code></td><td style="text-align:right;"><code>%%</code></td></tr><tr><td style="text-align:right;">the close</td><td style="text-align:right;"><code class="gm-ml"><span class="gm-sg">#]</span></code></td><td style="text-align:right;"><code class="gm-ml"><span class="gm-sg">//]</span></code></td><td style="text-align:right;"><code class="gm-ml"><span class="gm-sg">%]</span></code></td></tr></tbody></table><p>A metaLine&#39;s content — e.g. labels, visibility actions, conditions, etc. — is written the same way in every format; only the marker in front of it changes. At this release <span class="gm-name">GoMeta</span> reads these three comment markers; the marker is named when <span class="gm-name">GoMeta</span> is called (Julia is the default), never inferred from the file, and the committed examples are Julia files. <span class="gm-name">GoMeta</span> is meant for all kinds of comments: the <a href="https://gometa.dev/talk/" target="_blank" rel="noreferrer">JuliaCon 2026 talk</a> lists Julia and Python, C and Rust, and LaTeX as implemented, Word documents (the <code><span class="gm-nb">.fodt</span></code> format to start with), and, not yet, spreadsheets and metadata attached to images, video and the like. That reach is the reason for the name — <span class="gm-name">GoMeta</span> works in between them, behind them, within them — stated on the <a href="./../">front page</a>.</p><p>The metadata lives next to the host&#39;s content, woven into the source, and the host is not aware of it. That is what makes <span class="gm-name">GoMeta</span> language- and format-agnostic: the metadata remains &quot;hidden&quot; within the comments, as the talk puts it, so the same metadata can be used everywhere, whatever the host. Files that are not text (e.g. photos, music, video, etc.) may carry metadata fields of their own: some image formats, for instance, accept small chunks of text. <span class="gm-name">GoMeta</span> is designed to be attached to such files later, through those fields — the talk&#39;s &quot;attached to files themselves&quot;.</p><p>From here: <a href="./what-is-gometa">What is <span class="gm-name">GoMeta</span>?</a> — the idea whole; <a href="./../reference/syntax-and-semantics">Syntax &amp; semantics</a> — the notation&#39;s reference; <a href="./../examples/step-by-step">Step by step</a> — the ladder of examples, Julia files at this release.</p>',7)])])}const p=t(o,[["render",i]]);export{g as __pageData,p as default};
